    /** O desenho de cada tipo de veículo. */
    fun doVeiculo(tipo: TipoVeiculo): ImageVector = when (tipo) {
        TipoVeiculo.CARRO -> Carro
        TipoVeiculo.MOTO -> Moto
        TipoVeiculo.BIKE -> Bike
    }

    // -------------------------------------------------------------- montagem

    /**
     * Material Symbols vêm na grade de 960 com o topo em -960 ("0 -960 960 960"):
     * o grupo desce 960 para o desenho cair dentro da tela.
     */
    private fun icone(caminho: String): ImageVector {
        // Um caminho mal escrito não pode derrubar o app inteiro na abertura
        // (as abas usam estes ícones): no pior caso o ícone some.
        val nos = runCatching { addPathNodes(caminho) }.getOrElse { emptyList() }
        return ImageVector.Builder(
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 960f,
            viewportHeight = 960f
        )
            .addGroup(translationY = 960f)
            .addPath(pathData = nos, fill = SolidColor(Color.Black))
            .clearGroup()
            .build()
    }
